#!/usr/bin/env python3
from __future__ import annotations
import json, pathlib, sys, tomllib
ROOT=pathlib.Path(__file__).resolve().parents[1]
def text(p): return (ROOT/p).read_text()
checks=[]
def check(name,cond): checks.append((name,bool(cond)))
cargo=text('Cargo.toml'); core=text('crates/sparkbridge-core/src/lib.rs'); protocol=text('crates/sparkbridge-protocol/src/lib.rs'); cli=text('apps/sparkbridge-cli/src/main.rs')
profile=json.loads(text('config/certification/profile-1.0-candidate.json')); matrix=json.loads(text('config/certification/protocol-matrix.json')); manifest=json.loads(text('manifest.json')) if (ROOT/'manifest.json').exists() else {}
check('workspace version is 0.12.0','version = "0.12.0"' in cargo)
check('protocol intentionally frozen at 1.10','PROTOCOL_MINOR: u16 = 10' in protocol)
check('certification crate is workspace member','crates/sparkbridge-certification' in cargo)
check('release certification feature exists','ReleaseCertification' in core and 'ITERATION_12_CERTIFICATION' in core)
check('server advertises certification feature','ITERATION_12_CERTIFICATION' in text('apps/sparkbridge-server/src/main.rs'))
check('certification profile release matches',profile.get('release')=='0.12.0')
check('certification profile protocol frozen',profile.get('protocol')=='1.10')
check('certification profile schema frozen',profile.get('database_schema')==9)
check('four native Rust targets required',all(x in profile['required_checks'] for x in ['rust.linux-x86_64','rust.linux-aarch64-dgx','rust.macos-arm64','rust.windows-x86_64']))
check('control-plane E2E required','e2e.control-plane' in profile['required_checks'])
check('agent repair E2E required','e2e.agent-repair' in profile['required_checks'])
check('three main fault drills required',all(x in profile['required_checks'] for x in ['fault.server-restart','fault.executor-disconnect','fault.ollama-restart']))
check('backup restore drill required','drill.backup-restore' in profile['required_checks'])
check('upgrade rollback drill required','drill.upgrade-rollback' in profile['required_checks'])
check('protocol previous/current required',all(x in profile['required_checks'] for x in ['compat.protocol-1.9','compat.protocol-1.10']))
check('audit chain certification required','security.audit-chain' in profile['required_checks'])
check('protocol matrix rejects next major',any(c['client']=='2.0' and not c['compatible'] for c in matrix['cases']))
check('protocol matrix negotiates previous minor',any(c['client']=='1.9' and c['negotiated']=='1.9' for c in matrix['cases']))
cert=text('crates/sparkbridge-certification/src/lib.rs')
check('certification evaluator blocks skipped required checks','required check' in cert and 'release_ready: failures.is_empty()' in cert)
check('certification evaluator checks release identity','release mismatch' in cert and 'protocol mismatch' in cert and 'schema mismatch' in cert)
check('certification evaluator supports performance thresholds','MetricThreshold' in cert and 'maximum' in cert and 'minimum' in cert)
check('certification profile requires source revision',profile.get('require_source_revision') is True)
check('certification profile requires evidence on PASS',profile.get('require_evidence_for_pass') is True)
check('certification bundle records source revision','source_revision' in cert and 'BundleProvenance' in cert)
check('certification checks support hashed evidence files','EvidenceFile' in cert and 'evidence_files' in cert)
check('evaluator rejects evidence-free required PASS','required passing check' in cert)
check('evaluator validates evidence digests','invalid evidence digest' in cert)
check('CLI exposes certification evaluate','CertificationCommand::Evaluate' in cli and 'sparkbridge_certification::evaluate' in cli)
check('CLI exposes certification template','CertificationCommand::Template' in cli and 'candidate_profile' in cli)
check('local result generator exists',(ROOT/'scripts/certification/generate_local_results.py').exists())
check('local result generator pins source revision','source_revision()' in text('scripts/certification/generate_local_results.py'))
check('source revision ignores Python/build/certification output caches','__pycache__' in text('scripts/certification/common.py') and '.pyc' in text('scripts/certification/common.py') and 'target/' in text('scripts/certification/common.py') and 'certification-run/' in text('scripts/certification/common.py'))
# OS droppings are not source: if they were hashed, the certified revision would differ
# between machines for the same release tree.
check('source revision ignores OS and editor droppings',"'.DS_Store'" in text('scripts/certification/common.py') and 'Thumbs.db' in text('scripts/certification/common.py') and '.idea/' in text('scripts/certification/common.py'))
check('droppings are gitignored','.DS_Store' in text('.gitignore') and '__pycache__/' in text('.gitignore'))
# Certification evidence logs are release content: the bundle references them by digest,
# so `*.log` must not silently drop them from version control.
check('certification evidence logs are not gitignored','!certification-evidence/*.log' in text('.gitignore'))
check('release inventory ships Cargo.lock','Cargo.lock' in text('PROJECT_FILES.txt'))
check('local result generator hashes evidence','evidence_ref' in text('scripts/certification/generate_local_results.py'))
check('merge rejects mixed source revisions','mixed source revisions cannot be certified' in text('scripts/certification/merge_results.py'))
check('merge rejects conflicting metrics','conflicting metric' in text('scripts/certification/merge_results.py'))
check('manual check recorder exists',(ROOT/'scripts/certification/record_check.py').exists())
check('release blocker renderer exists',(ROOT/'scripts/certification/release_blockers.py').exists())
check('protocol fixture checker exists',(ROOT/'scripts/certification/check_protocol_matrix.py').exists())
check('backup restore drill exists',(ROOT/'scripts/certification/backup_restore_drill.sh').exists())
check('update rollback drill exists',(ROOT/'scripts/certification/update_rollback_drill.sh').exists())
check('fault plan is machine readable',(ROOT/'scripts/certification/fault_plan.json').exists())
maint=text('crates/sparkbridge-maintenance/src/lib.rs')
check('backup restore has native Rust unit drill','backup_restore_round_trip' in maint)
check('signed update has native Rust unit drill','signed_update_verifies_and_stages' in maint)
ci=text('.github/workflows/ci.yml')
check('CI matrix includes Linux macOS Windows',all(x in ci for x in ['ubuntu-latest','macos-latest','windows-latest']))
check('CI uploads certification evidence','certification-${{ matrix.os }}' in ci and 'certification-results.local.json' in ci and 'certification-evidence/' in ci)
check('CI aggregates platform evidence','certification-aggregate' in ci and ('merge_results.py' in ci or 'assemble_evidence_bundle.py' in ci) and 'release_blockers.py' in ci)
check('DGX self-hosted certification workflow exists',(ROOT/'.github/workflows/certification-dgx.yml').exists() and 'dgx-spark' in text('.github/workflows/certification-dgx.yml'))
check('CI retains MSRV lane','rust-toolchain@1.85.0' in ci)
check('CI does not gate on cargo fmt','cargo fmt' not in ci)

# The result templates must satisfy the schema docs/CERTIFICATION.md points readers at.
# A `null` source_revision silently failed this, so the templates shipped unvalidatable.
schema=json.loads(text('config/certification/evidence-bundle.schema.json'))
def conforms(path):
    obj=json.loads(text(path))
    if any(key not in obj for key in schema['required']):return False
    revision=obj.get('source_revision')
    return isinstance(revision,str) and len(revision)>=1
check('results template conforms to the evidence bundle schema',conforms('config/certification/results-template.json'))
check('platform result template conforms to the evidence bundle schema',conforms('config/certification/platform-result-template.json'))
check('local result bundle conforms to the evidence bundle schema',conforms('certification-results.local.json'))
check('Linux server installer creates service account','useradd' in text('packaging/linux/install-server.sh'))
check('Linux uninstallers bundled',(ROOT/'packaging/linux/uninstall-server.sh').exists() and (ROOT/'packaging/linux/uninstall-executor.sh').exists())
check('macOS uninstaller bundled',(ROOT/'packaging/macos/uninstall-executor.sh').exists())
check('certification guide bundled',(ROOT/'docs/CERTIFICATION.md').exists())
check('compatibility guide bundled',(ROOT/'docs/COMPATIBILITY.md').exists())
check('threat model bundled',(ROOT/'docs/THREAT_MODEL.md').exists())
check('performance guide bundled',(ROOT/'docs/PERFORMANCE.md').exists())
check('manual remains bundled',(ROOT/'docs/USER_MANUAL.md').exists() and (ROOT/'docs/INSTALLATION_GUIDE.md').exists())
check('manifest marks manuals bundled',manifest.get('manuals_bundled') is True if manifest else True)

check('rc3 certification tooling self-test exists',(ROOT/'scripts/certification/selftest_rc3.py').exists())
check('one-command certification runner exists',(ROOT/'scripts/certification/certify_revision.py').exists() and (ROOT/'scripts/certify.sh').exists())
check('certification runner assembles portable evidence','assemble_evidence_bundle.py' in text('scripts/certification/certify_revision.py') and 'verify_evidence_bundle.py' in text('scripts/certification/assemble_evidence_bundle.py'))
check('evidence verifier checks digest and size','digest mismatch' in text('scripts/certification/verify_evidence_bundle.py') and 'size mismatch' in text('scripts/certification/verify_evidence_bundle.py'))
check('assembled evidence bundle rewrites portable paths','relative_to(out).as_posix()' in text('scripts/certification/assemble_evidence_bundle.py'))
check('assembled bundle emits evidence manifest','evidence-manifest.json' in text('scripts/certification/assemble_evidence_bundle.py'))
check('blocker renderer checks release identity','identity.release' in text('scripts/certification/release_blockers.py') and 'identity.protocol' in text('scripts/certification/release_blockers.py'))
check('blocker renderer checks metric thresholds','metric_thresholds' in text('scripts/certification/release_blockers.py') and 'above_maximum' in text('scripts/certification/release_blockers.py'))
check('triage renderer gives actionable next steps',(ROOT/'scripts/certification/triage_results.py').exists() and 'next_action' in text('scripts/certification/triage_results.py'))
check('runner example avoids embedded token values',(ROOT/'config/certification/runner.example.json').exists() and 'SPARKBRIDGE_GATEWAY_TOKEN' not in text('config/certification/runner.example.json') and 'SPARKBRIDGE_INTEGRATION_TOKEN' not in text('config/certification/runner.example.json'))
check('CI assembles and verifies portable evidence','assemble_evidence_bundle.py' in ci and 'verify_evidence_bundle.py' in ci and 'triage_results.py' in ci)
check('DGX workflow runs one-command certification','scripts/certify.sh' in text('.github/workflows/certification-dgx.yml'))
check('no schema bump for certification','SCHEMA_VERSION: u32 = 9' in text('apps/sparkbridge-server/src/store.rs'))
failed=[n for n,c in checks if not c]
for n,c in checks: print(('PASS' if c else 'FAIL')+': '+n)
if failed:
    print(f'\n{len(failed)} certification/hardening invariant(s) failed',file=sys.stderr); sys.exit(1)
print(f'\nCertification + Hardening audit passed: {len(checks)} invariants')
